export const twelveDayDay1Posts = twelveDayDay1Drafts.map(p=>({...p,cluster:"concepts",editorialStatus:twelveDayRelease.published?"published":"draft",published:twelveDayRelease.date,modified:twelveDayRelease.date}));

export function applyTwelveDayExistingReview(post) {
 if(post.slug!=="cash-flow-statement" || post.html.includes("cash-close-cutoff-control")) return post;
 if(post.modified>"2026-10-25") return post;
 return {...post, modified:twelveDayRelease.date, html:post.html+"<h2 id=\"cash-close-cutoff-control\">Check invoice cut-off before explaining the cash movement</h2><p>Keep three dates for a material credit transaction: delivery/recognition, invoice due date and bank settlement. A receipt against an opening receivable increases cash while reducing that asset; it is not another sale. A supplier payment settles a payable rather than automatically creating a second expense. Reconcile the subsidiary invoice ledgers to the balance-sheet control accounts before using their movements in the operating-cash bridge.</p><div class=\"article-table-scroll\"><table><caption>Illustrative cut-off checks; these do not change the statement example above</caption><thead><tr><th scope=\"col\">Record</th><th scope=\"col\">Question to resolve</th><th scope=\"col\">Evidence</th></tr></thead><tbody><tr><th scope=\"row\">Customer credit</th><td>Was the return recognized in the correct period?</td><td>Accepted credit and original invoice</td></tr><tr><th scope=\"row\">Unapplied receipt</th><td>Is cash posted without clearing the right receivable?</td><td>Bank receipt and customer remittance</td></tr><tr><th scope=\"row\">Supplier bill</th><td>Was an unpaid obligation omitted from the closing ledger?</td><td>Accepted delivery and supplier invoice</td></tr></tbody></table></div><p>Keep this close control separate from the <a href=\"/calculators/cash-flow-forecast-template/\">forecast of future receipts and payments</a>. The historical reconciliation must agree before its balances become forecast inputs.</p>"};
}
